#include <bits/stdc++.h>using namespace std; void O_o(){    int n;cin >> n;    for(int c = n;c >= 0;c--){        if(c == n){            cout << ((1 << n) - 1) << ' ';        }else{            int bit = n - c - 1;            for(int high = 0;high < (1 << bit);high++){                int x = (high << (c + 1)) | ((1 << c) - 1);                cout << x << ' ';            }        }    }    cout << '\n';} int main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    int T;cin >> T;    while(T--)O_o();    return 0;}